import { useEffect, useState } from "react";
import { getNaturePhotos } from "../services/api";

const fallbackPhotos = [
  {
    id: "forest",
    url: "https://images.unsplash.com/photo-1448375240586-882707db888b?w=1000",
    title: "Зелений ліс",
  },
  {
    id: "mountains",
    url: "https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=1000",
    title: "Гірські вершини",
  },
  {
    id: "lake",
    url: "https://images.unsplash.com/photo-1470770841072-f978cf4d019e?w=1000",
    title: "Озеро серед гір",
  },
  {
    id: "sunset",
    url: "https://images.unsplash.com/photo-1472120435266-53107fd0c44a?w=1000",
    title: "Захід сонця",
  },
];

function Gallery() {
  const [photos, setPhotos] = useState(fallbackPhotos);
  const [active, setActive] = useState(0);

  useEffect(() => {
    getNaturePhotos()
      .then((data) => {
        if (data.hits?.length) {
          setPhotos(
            data.hits.map((photo) => ({
              id: photo.id,
              url: photo.largeImageURL,
              title: photo.tags || "Природа",
            }))
          );
        }
      })
      .catch(() => {
        // Показуємо запасні фотографії, якщо API недоступний.
      });
  }, []);

  function move(direction) {
    setActive(
      (current) => (current + direction + photos.length) % photos.length
    );
  }

  const photo = photos[active];

  return (
    <section className="section gallery-section" id="gallery">
      <div className="section-heading">
        <div>
          <span className="eyebrow">КРАСА НАВКОЛО НАС</span>
          <h2>Галерея природи</h2>
        </div>
        <div className="gallery-controls">
          <button onClick={() => move(-1)} aria-label="Попереднє фото">
            ←
          </button>
          <button onClick={() => move(1)} aria-label="Наступне фото">
            →
          </button>
        </div>
      </div>

      <div className="gallery-slider">
        <img src={photo.url} alt={photo.title} key={photo.id} />
        <div className="gallery-caption">
          <span>
            {String(active + 1).padStart(2, "0")} /{" "}
            {String(photos.length).padStart(2, "0")}
          </span>
          <h3>{photo.title}</h3>
        </div>
      </div>

      <div className="gallery-dots">
        {photos.map((item, index) => (
          <button
            key={item.id}
            className={index === active ? "active" : ""}
            onClick={() => setActive(index)}
            aria-label={`Фото ${index + 1}`}
          />
        ))}
      </div>
    </section>
  );
}

export default Gallery;
